css:
.ipo-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.ipo-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-left: 4px solid #00ff88;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.05);
    gap: 16px;
    flex-wrap: wrap;
}
.ipo-sim-title h1 {
    color: #00ff88;
    font-size: 1.3rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 4px 0;
    font-weight: 700;
}
.ipo-sim-subtitle {
    color: #7a8899;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.ipo-sim-round-indicator {
    background: #111827;
    border: 1px solid #1f2d3d;
    padding: 10px 22px;
    border-radius: 6px;
    font-size: 1.15rem;
    color: #00bfff;
    font-weight: 700;
    letter-spacing: 0.05em;
}
.ipo-sim-round-label {
    color: #6b7280;
    font-size: 0.68rem;
    letter-spacing: 0.18em;
    margin-right: 10px;
    text-transform: uppercase;
}
.ipo-sim-round-sep {
    color: #3a4a5e;
    margin: 0 4px;
}
.ipo-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.ipo-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.ipo-sim-kpi-card:hover {
    border-color: #2d3f55;
    transform: translateY(-2px);
}
.ipo-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.ipo-sim-kpi-label {
    color: #6b7280;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.ipo-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #00ff88;
    letter-spacing: 0.02em;
}
.ipo-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.ipo-sim-briefing-header {
    color: #00bfff;
    font-size: 0.82rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid #1f2d3d;
}
.ipo-sim-briefing-body {
    color: #c5cdd8;
    font-size: 0.92rem;
    line-height: 1.65;
}
.ipo-sim-briefing-body strong {
    color: #e0e6f0;
    font-weight: 600;
}
.ipo-sim-briefing-body em {
    color: #00ff88;
    font-style: normal;
    font-weight: 600;
}
.ipo-sim-decisions {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 26px;
    margin-bottom: 20px;
}
.ipo-sim-decisions h3 {
    color: #00ff88;
    font-size: 0.88rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1f2d3d;
    font-weight: 700;
}
.ipo-sim-decision-group {
    margin-bottom: 20px;
}
.ipo-sim-decision-group:last-child {
    margin-bottom: 0;
}
.ipo-sim-decision-label {
    display: block;
    color: #9aa5b1;
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
    text-transform: uppercase;
    font-weight: 600;
}
.ipo-sim-decision-hint {
    color: #6b7280;
    font-size: 0.78rem;
    margin-bottom: 10px;
    font-style: italic;
    line-height: 1.5;
}
.ipo-sim-decisions select,
.ipo-sim-decisions input[type="number"],
.ipo-sim-decisions input[type="text"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
}
.ipo-sim-decisions select:focus,
.ipo-sim-decisions input:focus {
    border-color: #00bfff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.15);
}
.ipo-sim-decisions select option {
    background: #111827;
    color: #e0e6f0;
}
.ipo-sim-checkbox-row {
    display: flex;
    gap: 22px;
    flex-wrap: wrap;
    padding: 8px 0;
}
.ipo-sim-checkbox-row label {
    color: #c5cdd8;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    margin: 0;
}
.ipo-sim-checkbox-row input[type="checkbox"] {
    accent-color: #00ff88;
    width: 16px;
    height: 16px;
}
.ipo-sim-actions {
    display: flex;
    gap: 12px;
    margin-bottom: 24px;
    flex-wrap: wrap;
}
.ipo-sim-actions .btn-primary {
    background: linear-gradient(135deg, #00ff88, #00bfff);
    border: none;
    color: #0a0f1e;
    padding: 13px 32px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border-radius: 6px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    font-size: 0.85rem;
}
.ipo-sim-actions .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0,255,136,0.35);
    color: #0a0f1e;
}
.ipo-sim-actions .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #9aa5b1;
    padding: 13px 22px;
    border-radius: 6px;
    font-size: 0.8rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}
.ipo-sim-actions .btn-outline-secondary:hover {
    background: #1a2436;
    color: #c5cdd8;
    border-color: #3a4a5e;
}
.ipo-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.ipo-sim-history table {
    color: #c5cdd8;
    font-size: 0.82rem;
    margin-bottom: 0;
    width: 100%;
}
.ipo-sim-history th {
    color: #00bfff;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    border-bottom: 1px solid #1f2d3d;
    padding: 10px 12px;
    background: transparent;
    font-weight: 600;
}
.ipo-sim-history td {
    border-top: none;
    border-bottom: 1px solid #1a2436;
    padding: 10px 12px;
    color: #c5cdd8;
}
.ipo-sim-history tr:hover td {
    background: rgba(0,191,255,0.04);
}
.ipo-sim-history tbody tr:last-child td {
    border-bottom: none;
}
.ipo-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    height: 360px;
    margin-bottom: 24px;
}
.ipo-sim-round-panel {
    display: none;
}
.ipo-sim-round-panel.active {
    display: block;
    animation: ipoFadeIn 0.3s ease;
}
@keyframes ipoFadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 768px) {
    .ipo-sim-container { padding: 14px; }
    .ipo-sim-header { flex-direction: column; align-items: flex-start; gap: 10px; padding: 16px 18px; }
    .ipo-sim-title h1 { font-size: 1.0rem; }
    .ipo-sim-kpi-value { font-size: 1.4rem; }
    .ipo-sim-decisions { padding: 18px; }
    .ipo-sim-checkbox-row { flex-direction: column; gap: 10px; }
    .ipo-sim-chart { height: 280px; }
}

