(function() {
    'use strict';

    class PrismviewIPOAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The S-1 Filing: Prismview Analytics IPO';
            this.version = '1.1.0';

            // Peer-group EV/ARR multiples
            this.PEER_MULTIPLES = {
                ai_adjacent:     11.4,
                horizontal_saas:  8.6,
                data_infra:      14.2,
                vertical:         7.1
            };

            // Base company fundamentals
            this.ARR         = 180;   // $M
            this.NET_DEBT    = 11;    // $M ($95M debt - $84M cash)
            this.PRE_IPO_DS  = 108;   // M shares pre-IPO, fully diluted
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    disclosureIntegrity: 100,
                    bookQuality:          50,
                    impliedValuation:   2540,   // $M at midpoint
                    bankRelationship:     70,
                    governanceScore:     100,
                    regulatoryScore:     100,
                    syndicateEconomics:   70,
                    spreadPct:           6.5,
                    sharesPrimary:       22,   // M
                    peerMultiple:       8.6,
                    priceRange:       'hold',
                    dealPulled:        false,
                    restated:          false,
                    finalPrice:            0,
                    day1Close:             0,
                    day1PopPct:            0,
                    netProceedsM:          0,
                    dealQualityScore:      0,

                    // R2 choices held for R4 consistency checks
                    r2InquiryChoice:    null,

                    // chart history arrays (required)
                    integrityHistory:   [],
                    bookHistory:        [],
                    valuationHistory:   [],
                    scoreHistory:       []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = state.currentPeriod || 1;

            // Make sure the correct panel is visible before reading inputs
            this._updateBriefing(state);

            if (round === 1) {
                var peer = document.getElementById('peerGroupInput');
                var range = document.getElementById('priceRangeInput');
                var sec   = document.getElementById('secondaryInput');
                var spr   = document.getElementById('spreadInput');
                if (peer)  decisions.peerGroup   = peer.value;
                if (range) decisions.priceRange  = range.value;
                if (sec)   decisions.secondary   = sec.value;
                if (spr)   decisions.spreadPct   = parseFloat(spr.value);
            } else if (round === 2) {
                var inq = document.getElementById('inquiryDisclosureInput');
                var mm  = document.getElementById('memeRfInput');
                var md  = document.getElementById('mdaInput');
                var dc  = document.getElementById('govDualClass');
                var sg  = document.getElementById('govStaggered');
                var fo  = document.getElementById('govForum');
                var rb  = document.getElementById('rule10b51Input');
                if (inq) decisions.inquiryDisclosure = inq.value;
                if (mm)  decisions.memeRf            = mm.value;
                if (md)  decisions.mdaProminence     = md.value;
                if (dc)  decisions.govDualClass      = !!dc.checked;
                if (sg)  decisions.govStaggered      = !!sg.checked;
                if (fo)  decisions.govForum          = !!fo.checked;
                if (rb)  decisions.rule10b51         = rb.value;
            } else if (round === 3) {
                var pt = document.getElementById('priceTalkInput');
                var up = document.getElementById('upsizeInput');
                var tl = document.getElementById('timelineInput');
                var sl = document.getElementById('signalingInput');
                if (pt) decisions.priceTalk  = pt.value;
                if (up) decisions.upsize     = parseInt(up.value, 10);
                if (tl) decisions.timeline   = tl.value;
                if (sl) decisions.signaling  = sl.value;
            } else if (round === 4) {
                var sr = document.getElementById('secResponseInput');
                var ac = document.getElementById('ascInput');
                var cc = document.getElementById('concentrationInput');
                if (sr) decisions.secResponse    = sr.value;
                if (ac) decisions.ascPosition    = ac.value;
                if (cc) decisions.concentration  = cc.value;
            } else if (round === 5) {
                var fp = document.getElementById('finalPriceInput');
                var al = document.getElementById('allocationInput');
                var gs = document.getElementById('greenShoeInput');
                var d1 = document.getElementById('day1Input');
                if (fp) decisions.finalPrice  = fp.value;
                if (al) decisions.allocation  = al.value;
                if (gs) decisions.greenShoe   = gs.value;
                if (d1) decisions.day1Posture = d1.value;
            }
            return true;
        }

        calculateResults(state) {
            var d  = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod || 1;

            var dInt = 0, dBook = 0, dBank = 0, dGov = 0, dReg = 0, dSynd = 0;
            var notes = [];

            if (round === 1) {
                // Peer group effect on valuation + integrity/book
                var peer = d.peerGroup || 'horizontal_saas';
                var mult = this.PEER_MULTIPLES[peer] || 8.6;
                ds.peerMultiple = mult;

                if (peer === 'ai_adjacent')      { dInt -= 5; dBook += 5;  notes.push('AI-adjacent positioning is aspirational; institutional PMs may discount.'); }
                else if (peer === 'horizontal_saas') { dInt += 5; dBook += 3; notes.push('Horizontal SaaS peer set is the most defensible anchor.'); }
                else if (peer === 'data_infra')  { dInt += 3; dBook += 8;  notes.push('Data-infra set supports aspirational multiples with some fit risk.'); }
                else if (peer === 'vertical')    { dInt += 2; dBook -= 5;  notes.push('Vertical analytics set reads too narrow for scale investors.'); }

                // Valuation recompute from peer
                var ev = mult * this.ARR;           // EV in $M
                var equityFromEv = ev - this.NET_DEBT; // EV + Cash - Debt; here Net Debt = +11
                // Midpoint price comparative: just map EV/ARR through to implied equity value
                // We keep a simplified $M equity value (valuation display)
                ds.impliedValuation = Math.round(ev + (84 - 95)); // EV - net debt to get equity

                // Price range
                var pr = d.priceRange || 'hold';
                ds.priceRange = pr;
                if (pr === 'tighten') { dInt += 2; notes.push('Tightening the range signals confidence — effective if book supports it.'); }
                else if (pr === 'widen') { dBook -= 3; notes.push('Widening the range signals uncertainty to institutional investors.'); }

                // Secondary tranche
                var sec = d.secondary || 'primary_only';
                if (sec === 'primary_only') { dBook += 5; notes.push('Primary-only optics: no insider selling at IPO.'); }
                else { dBook -= 3; notes.push('Secondary tranche weakens message on insider conviction.'); }

                // Gross spread
                var spr = parseFloat(d.spreadPct) || 6.5;
                ds.spreadPct = spr;
                if (spr === 7.0)        { dBank += 5; dSynd += 10; notes.push('Standard 7% spread; bank relationships reinforced.'); }
                else if (spr === 6.5)   { dSynd += 0; notes.push('Negotiated 6.5% spread — market-standard compromise.'); }
                else if (spr === 6.25)  { dBank -= 5; dSynd -= 10; notes.push('Aggressive 6.25% push — bankers will remember.'); }

            } else if (round === 2) {
                // SEC inquiry disclosure
                var inq = d.inquiryDisclosure || 'limited';
                ds.r2InquiryChoice = inq;
                if (inq === 'full')        { dInt += 20; dReg += 10; notes.push('Full SEC inquiry disclosure: the integrity-defining move.'); }
                else if (inq === 'limited'){ dInt -= 5;               notes.push('Limited disclosure risks staff push-back at comment stage.'); }
                else if (inq === 'none')   { dInt -= 30; dReg -= 30;  notes.push('Non-disclosure: highest-risk choice; TSC/Basic materiality exposure.'); }

                // Meme-stock RF
                if (d.memeRf === 'include') { dInt += 2; notes.push('Meme-stock RF included (litigation-mitigation).'); }

                // MD&A prominence
                var md = d.mdaProminence || 'balanced';
                if (md === 'non_gaap_lead') { dInt -= 5; dBook += 3; notes.push('Non-GAAP-led MD&A: SEC may comment under Reg G.'); }
                else if (md === 'balanced') { dInt += 5;             notes.push('Balanced GAAP / non-GAAP with Reg G reconciliation is Corp Fin best practice.'); }
                else if (md === 'gaap_first'){ dBook -= 5;           notes.push('GAAP-first understates the SaaS metric stack.'); }

                // Governance package
                var govHits = 0;
                if (d.govDualClass) { dGov -= 15; govHits += 1; }
                if (d.govStaggered) { dGov -= 10; govHits += 1; }
                if (d.govForum)     { dGov += 5; }
                if (govHits >= 2) notes.push('ISS / Glass Lewis likely to issue adverse recommendation.');
                else if (govHits === 1) notes.push('Governance has one red flag — expect a mixed ISS report.');

                // 10b5-1
                if (d.rule10b51 === 'pre_announce') { dInt += 3; dBank += 3; notes.push('Pre-announced 10b5-1 plans reduce post-lockup volatility risk.'); }
                else { dInt -= 2; }

            } else if (round === 3) {
                // Price talk
                var pt = d.priceTalk || 'hold';
                if (pt === 'hold')            { dInt += 5; dBook += 3; notes.push('Disciplined price-talk hold preserves book quality.'); }
                else if (pt === 'bump_20_22') { dBook += 2; notes.push('Modest price-talk bump; demand should absorb.'); }
                else if (pt === 'bump_21_23') { dInt -= 5; dBook -= 8; notes.push('Aggressive price-talk bump: LO demand compresses above $22.'); }

                // Upsize
                var up = d.upsize || 22;
                ds.sharesPrimary = up;
                if (up === 22)      { dBook += 3; notes.push('Holding size preserves scarcity and demand coverage.'); }
                else if (up === 25) { dBook += 0; notes.push('Modest upsize absorbed by book; price dynamic unchanged.'); }
                else if (up === 28) { dBook -= 8; dBank -= 3; notes.push('Aggressive upsize dilutes the book; covered ratio drops.'); }

                // Timeline
                var tl = d.timeline || 'hold';
                if (tl === 'accelerate') { dBook -= 2; notes.push('Acceleration leaves some accounts without final sizing discipline.'); }
                else if (tl === 'extend'){ dBook -= 3; notes.push('Extension creates fatigue and signals weakness.'); }

                // Allocation signaling
                if (d.signaling === 'tell') { dBook += 5; dBank += 3; notes.push('Anchor LOs signaled full — strengthens commitment.'); }

            } else if (round === 4) {
                // SEC inquiry response (coherence with R2)
                var sr = d.secResponse || 'update_rf';
                var r2 = ds.r2InquiryChoice || 'limited';

                if (sr === 'update_rf') {
                    if (r2 === 'none')   { dInt -= 5;  dReg -= 10; notes.push('Late disclosure cleans the record but flags a materiality miss at R2.'); }
                    else                 { dInt += 10; dReg += 10; notes.push('Risk factor update accepted by staff without escalation.'); }
                } else if (sr === 'position_letter') {
                    dInt -= 15; dReg -= 20; notes.push('Position letter rarely persuades on informal-inquiry disclosure questions.');
                } else if (sr === 'delay') {
                    dInt -= 10; dReg -= 15; notes.push('Waiting for formal SEC action cedes narrative control.');
                }

                // ASC 606 position
                var ac = d.ascPosition || 'restate';
                if (ac === 'defend')       { dInt -= 20; dReg -= 25; notes.push('Defending SSP methodology against Round C staff push rarely succeeds.'); }
                else if (ac === 'prospective') { dInt -= 10; dReg -= 10; notes.push('Prospective revision without restating risks staff acceleration refusal.'); }
                else if (ac === 'restate') { dInt += 15; dReg += 5; ds.restated = true; notes.push('Restatement: painful 45–60 day delay but clean-deal outcome.'); }

                // Customer concentration
                if (d.concentration === 'named') { dInt += 5; dBank -= 2; notes.push('Named 11% customer: best disclosure integrity, small relationship cost.'); }
                else { dInt += 2; notes.push('Unnamed quantified disclosure: staff-acceptable middle path.'); }

            } else if (round === 5) {
                // PRICING NIGHT
                var alloc = d.allocation || 'lo_heavy';
                var shoe  = d.greenShoe  || 'naked_short';
                var day1  = d.day1Posture || 'stabilize';
                var priceChoice = d.finalPrice || '22';

                if (priceChoice === 'pull') {
                    ds.dealPulled = true;
                    ds.finalPrice = 0;
                    ds.netProceedsM = 0;
                    ds.day1PopPct = 0;
                    ds.day1Close  = 0;
                    dInt += 5; dBank -= 15;
                    notes.push('Deal pulled. Integrity preserved; issuer relationship strained; refile in 90–120 days.');
                } else {
                    var p = parseFloat(priceChoice);
                    ds.finalPrice = p;

                    var shares = ds.sharesPrimary || 22;
                    var gross  = p * shares;
                    var net    = gross * (1 - (ds.spreadPct / 100));
                    ds.netProceedsM = Math.round(net * 100) / 100;

                    // Base Day-1 pop by price vs. demand
                    var basePop;
                    if (p <= 20)      basePop = 18;
                    else if (p === 22) basePop = 16;
                    else if (p === 23) basePop = 10;
                    else if (p === 24) basePop = 6;
                    else               basePop = -2; // $25 break-issue risk

                    // Allocation adjustment
                    if (alloc === 'lo_heavy')      basePop += 4;
                    else if (alloc === 'balanced') basePop += 0;
                    else if (alloc === 'hf_concession') basePop -= 8;

                    // Book-quality and integrity adjustments
                    if (ds.bookQuality > 70) basePop += 3;
                    if (ds.bookQuality < 30) basePop -= 4;
                    if (ds.disclosureIntegrity < 50) basePop -= 5;

                    // Day-1 posture / shoe
                    if (day1 === 'stabilize')     basePop += 2;
                    else if (day1 === 'no_bid')   basePop -= 3;
                    else if (day1 === 'penalty')  basePop += 1;

                    if (shoe === 'naked_short')   basePop += 1;
                    else if (shoe === 'partial')  basePop += 0;
                    else if (shoe === 'exercise_full') basePop -= 2;

                    // Random shock ±2
                    var shock = (Math.random() * 4) - 2;
                    basePop += shock;

                    ds.day1PopPct = Math.round(basePop * 10) / 10;
                    ds.day1Close  = Math.round(p * (1 + basePop / 100) * 100) / 100;

                    // Allocation quality score component
                    if (alloc === 'lo_heavy')          { dBank += 10; dSynd += 5; notes.push('Long-only heavy allocation: 85% LO stickiness — the bookrunner reusable asset.'); }
                    else if (alloc === 'balanced')     { dBank += 3;  notes.push('Balanced allocation: middle-path stickiness.'); }
                    else if (alloc === 'hf_concession'){ dBank -= 10; notes.push('HF concession allocation: aftermarket volatility and flipping risk.'); }

                    if (shoe === 'naked_short')      notes.push('Naked short held for stabilization — Reg M compliant, maximum firepower Day 1.');
                    else if (shoe === 'partial')     notes.push('Partial green-shoe exercise balances stabilization with issuer optionality.');
                    else if (shoe === 'exercise_full') notes.push('Full shoe exercise Day 1 removes stabilization firepower.');

                    if (day1 === 'stabilize')        notes.push('Stabilizing bid at offer keeps the print clean.');
                    else if (day1 === 'penalty')     notes.push('Penalty bids deter flippers but test anchor LO patience.');
                    else if (day1 === 'no_bid')      notes.push('No bid: pure market discovery, higher break-issue risk.');

                    if (basePop < 0)      { dBank -= 10; notes.push('Deal broke issue on Day 1 — lasting relationship cost.'); }
                    else if (basePop > 35){ dBank -= 5;  notes.push('Day 1 pop >35% — money left on the table frustrates issuer.'); }
                    else if (basePop >= 10 && basePop <= 20) { dBank += 5; notes.push('Clean 10–20% Day 1 pop — textbook Loughran-Ritter outcome.'); }
                }
            }

            // Apply deltas (with clamping)
            ds.disclosureIntegrity = Math.max(0, Math.min(100, ds.disclosureIntegrity + dInt));
            ds.bookQuality         = Math.max(0, Math.min(100, ds.bookQuality + dBook));
            ds.bankRelationship    = Math.max(0, Math.min(100, ds.bankRelationship + dBank));
            ds.governanceScore     = Math.max(0, Math.min(100, ds.governanceScore + dGov));
            ds.regulatoryScore     = Math.max(0, Math.min(100, ds.regulatoryScore + dReg));
            ds.syndicateEconomics  = Math.max(0, Math.min(100, ds.syndicateEconomics + dSynd));

            // Composite score (only meaningful after R5, but computed each round for chart)
            var proceedsScore;
            if (ds.dealPulled) proceedsScore = 0;
            else if (ds.netProceedsM > 0) proceedsScore = Math.min(100, (ds.netProceedsM / 500) * 100);
            else proceedsScore = 50; // pre-pricing placeholder

            var day1Score;
            if (ds.dealPulled) day1Score = 20;
            else if (ds.finalPrice === 0) day1Score = 50;
            else if (ds.day1PopPct < 0) day1Score = 30;
            else if (ds.day1PopPct > 35) day1Score = 60;
            else if (ds.day1PopPct >= 10 && ds.day1PopPct <= 20) day1Score = 100;
            else if (ds.day1PopPct >= 5 && ds.day1PopPct < 10) day1Score = 85;
            else if (ds.day1PopPct > 20 && ds.day1PopPct <= 35) day1Score = 80;
            else day1Score = 70;

            var allocScore;
            var allocChoice = (d && d.allocation) || 'lo_heavy';
            if (ds.dealPulled) allocScore = 30;
            else if (ds.finalPrice === 0) allocScore = 50;
            else if (allocChoice === 'lo_heavy') allocScore = 90;
            else if (allocChoice === 'balanced') allocScore = 70;
            else allocScore = 45;

            var composite =
                0.20 * proceedsScore +
                0.15 * day1Score +
                0.15 * allocScore +
                0.15 * ds.disclosureIntegrity +
                0.10 * ds.syndicateEconomics +
                0.10 * ds.bankRelationship +
                0.05 * ds.governanceScore +
                0.10 * ds.regulatoryScore;
            ds.dealQualityScore = Math.round(composite * 10) / 10;

            // Persist score into domainState for the grading/reporting layer
            // (results_utils.php reads domainState.performance.overallScore -> score).
            ds.score = ds.dealQualityScore;
            ds.performance = { overallScore: ds.dealQualityScore, grade: this._grade(ds.dealQualityScore) };

            // Push history for chart
            ds.integrityHistory.push(ds.disclosureIntegrity);
            ds.bookHistory.push(ds.bookQuality);
            ds.valuationHistory.push(ds.impliedValuation);
            ds.scoreHistory.push(ds.dealQualityScore);

            var results = {
                period: state.currentPeriod,
                roundName: this._roundName(round),
                dIntegrity:   Math.round(dInt * 10) / 10,
                dBookQuality: Math.round(dBook * 10) / 10,
                disclosureIntegrity: ds.disclosureIntegrity,
                bookQuality:         ds.bookQuality,
                impliedValuation:    ds.impliedValuation,
                dealQualityScore:    ds.dealQualityScore,
                finalPrice:          ds.finalPrice,
                day1PopPct:          ds.day1PopPct,
                netProceedsM:        ds.netProceedsM,
                dealPulled:          ds.dealPulled,
                score:               ds.dealQualityScore,
                overallScore:        ds.dealQualityScore,
                note:                notes.join(' ')
            };

            // Advance briefing to next round
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });
            }, 400);

            return results;
        }

